       FROM orders o
       JOIN players pl ON pl.id = o.player_id
       WHERE o.user_id = $1::uuid AND o.link = $2 AND NOT (o.player_id = $3 AND o.provider = 'OB')
       ORDER BY o.provider, o.player_id`,
